+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.EnumSet;
+import java.util.Locale;
+import java.util.Set;
+
+/**
+ * The filters which can be applied to the customer list.
+ *
+ * <p>Name terms are prepared once when the filter is created, rather than for
+ * every page requested by the grid.
+ */
+public final class CustomerFilter {
+
+    private final String name;
+    private final Set<CustomerStatus> statuses;
+    private final String[] nameTerms;
+
+    public CustomerFilter(String name, Set<CustomerStatus> statuses) {
+        this.name = name == null ? "" : name;
+        this.statuses = statuses == null || statuses.isEmpty()
+                ? Set.of()
+                : Set.copyOf(EnumSet.copyOf(statuses));
+        this.nameTerms = Arrays.stream(this.name.trim().split("\\s+"))
+                .filter(term -> !term.isEmpty())
+                .map(CustomerFilter::fold)
+                .toArray(String[]::new);
+    }
+
+    public static CustomerFilter empty() {
+        return new CustomerFilter("", Set.of());
+    }
+
+    public boolean matches(Customer customer) {
+        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
+            return false;
+        }
+        String firstName = fold(customer.firstName());
+        String lastName = fold(customer.lastName());
+        return Arrays.stream(nameTerms)
+                .allMatch(term -> firstName.contains(term) || lastName.contains(term));
+    }
+
+    private static String fold(String value) {
+        return Normalizer.normalize(value, Normalizer.Form.NFD)
+                .replaceAll("\\p{M}+", "")
+                .toLowerCase(Locale.ROOT);
+    }
+}
